package com.pharmacy.controller;
import com.pharmacy.common.PageData;import com.pharmacy.enums.UserRole;import com.pharmacy.exception.GlobalExceptionHandler;import com.pharmacy.security.AuthenticatedUser;import com.pharmacy.service.OrderService;import org.junit.jupiter.api.*;import org.springframework.http.MediaType;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class UserOrderControllerTest {private OrderService service;private MockMvc mvc;@BeforeEach void setup(){service=mock(OrderService.class);mvc=MockMvcBuilders.standaloneSetup(new UserOrderController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();AuthenticatedUser u=new AuthenticatedUser(7L,"u","U",UserRole.USER);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}@Test void createRequiresKey()throws Exception{mvc.perform(post("/api/user/orders").contentType(MediaType.APPLICATION_JSON).content("{\"addressId\":1,\"cartItemIds\":[2]}")).andExpect(status().isBadRequest());}@Test void createPassesKey()throws Exception{when(service.create(eq(7L),any(),eq("key-1"))).thenReturn(Map.of("orderId",1));mvc.perform(post("/api/user/orders").header("Idempotency-Key","key-1").contentType(MediaType.APPLICATION_JSON).content("{\"addressId\":1,\"cartItemIds\":[2]}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.orderId").value(1));}@Test void pageIsScopedToUser()throws Exception{when(service.pageUserOrders(anyLong(),anyLong(),anyLong(),any())).thenReturn(new PageData<>(List.of(),0,1,10,0));mvc.perform(get("/api/user/orders")).andExpect(status().isOk());verify(service).pageUserOrders(7L,1,10,null);}}
